safari_navigator.agent_input_schema:
{
  "type": "object",
  "properties": {
    "current_area": { "type": "string", "description": "Current Safari Zone map" },
    "current_position": {
      "type": "object",
      "properties": {
        "x": { "type": "integer" },
        "y": { "type": "integer" }
      },
      "required": ["x", "y"]
    },
    "destination_area": { "type": "string", "description": "Target Safari Zone map" },
    "destination_coordinates": {
      "type": "object",
      "properties": {
        "x": { "type": "integer" },
        "y": { "type": "integer" }
      },
      "required": ["x", "y"]
    },
    "verified_waypoints": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Documented collision-free landmarks and elevation bridges"
    },
    "step_budget": { "type": "integer", "description": "Available step budget" }
  },
  "required": ["current_area", "current_position", "destination_area", "destination_coordinates", "verified_waypoints", "step_budget"]
}
